def thanos_sort(arr):
    def max_sorted_subarray_length(arr):
        if len(arr) <= 1:
            return arr

        mid = len(arr) // 2
        left = max_sorted_subarray_length(arr[:mid])
        right = max_sorted_subarray_length(arr[mid:])

        merged = []
        i = j = 0
        while i < len(left) and j < len(right):
            if left[i] <= right[j]:
                merged.append(left[i])
                i += 1
            else:
                merged.append(right[j])
                j += 1

        merged.extend(left[i:])
        merged.extend(right[j:])

        return merged

    def thanos_snap(arr):
        mid = len(arr) // 2
        return max(max_sorted_subarray_length(arr[:mid]), max_sorted_subarray_length(arr[mid:]))

    while len(arr) > 1:
        arr = thanos_snap(arr)

    return len(arr)

