def thanos_sort_max_length(arr):
    def dfs(left, right):
        if left >= right:
            return 0

        mid = (left + right) // 2
        left_sorted = dfs(left, mid)
        right_sorted = dfs(mid + 1, right)

        if arr[left] <= arr[mid]:
            left_len = mid - left + 1
        else:
            left_len = 0

        if arr[mid + 1] >= arr[right]:
            right_len = right - mid
        else:
            right_len = 0

        return max(left_len, right_len, left_sorted, right_sorted)

    return dfs(0, len(arr) - 1)

